Q: React useState not updating inside setInterval even with functional update A: <p>You need a way to always read the <em>current</em> state inside the interval. Combine <code>useRef</code> to hold the latest value without causing re‑runs:</p>
<p>javascript</p>
<pre><code>function Timer() {
  const [seconds, setSeconds] = useState(0);
  const secondsRef = useRef(seconds);

  // Keep ref updated on every render
  useEffect(() =&gt; {
    secondsRef.current = seconds;
  }, [seconds]);

  useEffect(() =&gt; {
    const interval = setInterval(() =&gt; {
      const currentSeconds = secondsRef.current;
      console.log(currentSeconds);
      setSeconds(currentSeconds + 1);
    }, 1000);

    return () =&gt; clearInterval(interval);
  }, []); // still empty – no need to re‑create interval

  return &lt;div&gt;{seconds}&lt;/div&gt;;
}
</code></pre>

Q: ExecuteNonQuery() - at System.RuntimeMethodHandle.InvokeMethod(Object target, Object[] arguments, Signature sig, Boolean constructor) A: <p>Here is the code:</p>
<pre><code>public void Main()

{
String FolderPath=Dts.Variables[&quot;User::FolderPath&quot;].Value.ToString();    

var directory = new DirectoryInfo(FolderPath);                          

 FileInfo[] files = directory.GetFiles();

 string fileFullPath = &quot;&quot;;

 foreach (FileInfo file in files)                                      

{

 string filename = &quot;&quot;;

 fileFullPath = FolderPath+&quot;\\&quot;+file.Name;                    

 filename = file.Name.Replace(&quot;.xlsx&quot;,&quot;&quot;);                    

 string ConStr;

 string HDR;

 HDR=&quot;YES&quot;;

 ConStr = &quot;Provider=Microsoft.ACE.OLEDB.12.0;Data Source=&quot; +  
           fileFullPath + &quot;;Extended Properties=\&quot;Excel 12.0;HDR=&quot; + 
           HDR + &quot;;IMEX=1\&quot;&quot;;  

 OleDbConnection cnn = new OleDbConnection(ConStr);

 cnn.Open();

 DataTable dtSheet = cnn.GetOleDbSchemaTable(OleDbSchemaGuid.Tables,  
                     null);  

 string sheetname;

 sheetname=&quot;&quot;;

 foreach (DataRow drSheet in dtSheet.Rows)

    {
       if (drSheet[&quot;TABLE_NAME&quot;].ToString().Contains(&quot;$&quot;))
         {
             sheetname=drSheet[&quot;TABLE_NAME&quot;].ToString();
             OleDbCommand oconn = new OleDbCommand(&quot;select * from [&quot; +  
                                  sheetname + &quot;]&quot;, cnn);
             OleDbDataAdapter adp = new OleDbDataAdapter(oconn);
             DataTable dt = new DataTable();
             adp.Fill(dt);
             string tableDDL = &quot;&quot;;
             tableDDL += &quot;IF Not EXISTS (SELECT * FROM sys.objects WHERE 
                          object_id = &quot;;
              tableDDL +=&quot;OBJECT_ID(N'[dbo].[&quot; + filename +&quot;]') AND  
                          type  in (N'U'))&quot;;
               tableDDL +=  &quot;Create table [&quot; + filename + &quot;]&quot;;
               tableDDL += &quot;(&quot;;
                 for (int i = 0; i &lt; dt.Columns.Count; i++)
                 {
                  if (i != dt.Columns.Count - 1)
                     tableDDL += &quot;[&quot; + dt.Columns[i].ColumnName + &quot;] &quot;  
                              +   &quot;NVarchar(max)&quot; + &quot;,&quot;;
                     else
                      tableDDL += &quot;[&quot; + dt.Columns[i].ColumnName + &quot;] &quot;  
                                      + &quot;NVarchar(max)&quot;;
                   }
                  tableDDL += &quot;)&quot;;

                 SqlConnection myADONETConnection = new SqlConnection();
                 myADONETConnection = (SqlConnection)  
                 (Dts.Connections[&quot;Connection 
                  Manager&quot;].AcquireConnection(Dts.Transaction) as 
                           SqlConnection);
                 SqlCommand myCommand = new SqlCommand(tableDDL,  
                  myADONETConnection);
                 myCommand.ExecuteNonQuery();

                 //Load the data from DataTable to SQL Server Table.
                 SqlBulkCopy blk = new SqlBulkCopy(myADONETConnection);
                 blk.DestinationTableName = &quot;[&quot; + filename +&quot;]&quot;;
                 blk.WriteToServer(dt);
            } 
        }
}
</code></pre>
